$files=@($relative|%{$p=Join-Path $ProjectPath $_;$i=Get-Item $p;[pscustomobject]@{relativePath=$_.Replace('\','/');bytes=[int64]$i.Length;sha256=Hash $p}});$roots=[ordered]@{verification=Test-Path (Join-Path $ProjectPath 'Research\Verification\Gate13R_36h_10pct_4Lane\v10');pilot=Test-Path (Join-Path $ProjectPath 'Research\PilotRuns\Gate13R_36h_10pct_4Lane\v10');clone=Test-Path 'H:\DDM_Final_Project_Gate13R36H\v10';formal=Test-Path (Join-Path $ProjectPath 'Research\FormalRuns\Gate13R_36h_10pct_4Lane\v1')}
$m=Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt10_Derivation_Partial_Manifest.v1.json';$f=Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt10_Derivation_Failure.v1.json';$c=Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt10_Derivation_Checkpoint.v1.json'
$mv=[ordered]@{schemaVersion=1;manifestKind='gate13r-36h-attempt10-derivation-partial-manifest-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-PRE-ROOT';files=$files;roots=$roots;unityProcessCount=@(Get-Process Unity -ErrorAction SilentlyContinue).Count;pilotStarted=$false;formalCampaign=$false;passed=$false};WriteAtomic $m $mv
$fv=[ordered]@{schemaVersion=1;receiptKind='gate13r-36h-attempt10-derivation-failure-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-PRE-ROOT';phase='deterministic-schedule-generation-plan-identity';errorMessage='Overlapping mechanical routes applied plan-v2 to plan-v10 and then matched the plan-v1 prefix inside plan-v10, producing invalid plan-v100 in the preparation module.';allowedRepair='A new versioned attempt may order the plan-v1 route before plan-v2 and assert that the derived plan identity is exactly the current plan ID with no duplicated zero.';partialManifestSha256=Hash $m;roots=$roots;unityProcessCount=$mv.unityProcessCount;pilotStarted=$false;formalCampaign=$false;passed=$false};WriteAtomic $f $fv
$cv=[ordered]@{schemaVersion=1;checkpointKind='gate13r-36h-attempt10-derivation-checkpoint-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='failed-no-resume';attempt=10;failedPhase='schedule-generation-plan-identity';failureReceiptSha256=Hash $f;partialManifestSha256=Hash $m;nextAllowedAction='Create a new versioned attempt with non-overlapping route order.';pilotStarted=$false;formalCampaign=$false;passed=$false};WriteAtomic $c $cv
